import java.util.*; public class WeeklyStaffPay { public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();double t=0;while(n-->0){String x=s.next(),name=s.next();double v=s.nextDouble(),p;if(x.equals("HOURLY")){double rate=s.nextDouble();p=v<=40?v*rate:40*rate+(v-40)*rate*1.5;}else p=v;t+=p;System.out.printf("%s: %.2f%n",name,p);}System.out.printf("Total Payroll: %.2f%n",t);} }
